typedef struct {
    const char *sym;
    const lv_image_dsc_t *px32;
    const lv_image_dsc_t *px16;
} ct_coin_entry_t;

// ค้นแบบไล่ทีละตัว ไม่ใช่ binary search — ตารางยาวได้ 32 แถว และการค้นเกิด
// เฉพาะตอนวาดหน้าใหม่ (ไม่เกินนาทีละครั้ง) ตารางที่ต้องเรียงถูกเสมอคือตารางที่
// พังเงียบได้ตอนมีคนเพิ่มไฟล์ ส่วน strcmp 32 ครั้งคือค่าที่วัดไม่ออก
static const ct_coin_entry_t s_coins[] = {
    {"ADA", &ct_coin_ADA_32, &ct_coin_ADA_16},
    {"AVAX", &ct_coin_AVAX_32, &ct_coin_AVAX_16},
    {"BNB", &ct_coin_BNB_32, &ct_coin_BNB_16},
    {"BTC", &ct_coin_BTC_32, &ct_coin_BTC_16},
    {"DOGE", &ct_coin_DOGE_32, &ct_coin_DOGE_16},
    {"DOT", &ct_coin_DOT_32, &ct_coin_DOT_16},
    {"ETH", &ct_coin_ETH_32, &ct_coin_ETH_16},
    {"LINK", &ct_coin_LINK_32, &ct_coin_LINK_16},
    {"LTC", &ct_coin_LTC_32, &ct_coin_LTC_16},
    {"SOL", &ct_coin_SOL_32, &ct_coin_SOL_16},
    {"TRX", &ct_coin_TRX_32, &ct_coin_TRX_16},
    {"XRP", &ct_coin_XRP_32, &ct_coin_XRP_16},
};

static const ct_coin_entry_t s_default = {
    "", &ct_coin__default_32, &ct_coin__default_16
};

static const ct_coin_entry_t *lookup(const char *sym)
{
    if (sym) {
        for (int i = 0; i < CT_COINS_COUNT; i++) {
            if (strcmp(s_coins[i].sym, sym) == 0) return &s_coins[i];
        }
    }
    return &s_default;
}

const lv_image_dsc_t *ct_coin_card(const char *sym) { return lookup(sym)->px32; }

const lv_image_dsc_t *ct_coin_row(const char *sym) { return lookup(sym)->px16; }
